import hashlib, json, re
from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
source = Path('products/services/catalogue-payhip/official-help.html')
base = 'https://help.payhip.com/'
class Links(HTMLParser):
    def __init__(self):
        super().__init__()
        self.href = None
        self.parts = []
        self.matches = {}
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.href = dict(attrs).get('href')
            self.parts = []
    def handle_data(self, text):
        if self.href:
            self.parts.append(text)
    def handle_endtag(self, tag):
        if tag != 'a' or not self.href:
            return
        url = urljoin(base, self.href)
        text = ' '.join(' '.join(self.parts).split())
        if urlsplit(url).scheme == 'https' and urlsplit(url).hostname in {'help.payhip.com', 'payhip.com'} and re.search(r'pricing|fees|payment gateway|payment processor|stripe|paypal|getting paid|payout|canada', text + ' ' + urlsplit(url).path, re.I):
            self.matches[url] = text
        self.href = None
raw = source.read_bytes()
links = Links()
links.feed(raw.decode('utf-8', errors='replace'))
result = {'source': base, 'source_sha256': hashlib.sha256(raw).hexdigest(), 'official_follow_up_leads': [{'url': url, 'label': label} for url, label in sorted(links.matches.items())], 'limit': 'Link labels identify follow-up leads only. Fees, Canadian eligibility, payout and activation require separate evidence.'}
out = Path('products/services/catalogue-payhip/official-help-links.json')
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
